package net.civeira.phylax.feature.observe.metric;

import java.util.List;
import java.util.Map;
import java.util.Set;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.store.ObsLog;
import net.civeira.phylax.feature.observe.store.ObsSpan;
import net.civeira.phylax.feature.observe.store.RetentionPolicy;
import net.civeira.phylax.feature.observe.store.TelemetryQuery;
import net.civeira.phylax.feature.observe.store.TelemetryStore;

class VitalsUnitTest {

  private static final TelemetryStore EMPTY = new TelemetryStore() {
    public void appendLogs(final List<ObsLog> logs) {}

    public void appendSpans(final List<ObsSpan> spans) {}

    public List<ObsLog> logs(final TelemetryQuery query) {
      return List.of();
    }

    public List<ObsSpan> spans(final TelemetryQuery query) {
      return List.of();
    }

    public List<ObsSpan> trace(final String traceId, final long from, final long to) {
      return List.of();
    }

    public List<ObsSpan> traces(final Set<String> traceIds, final long from, final long to) {
      return List.of();
    }

    public void appendPoints(final List<MetricPoint> points) {}

    public List<MetricPoint> points(final long from, final long to, final long step,
        final Set<String> sources) {
      return List.of();
    }

    public long sizeBytes() {
      return 0;
    }

    public void purge(final RetentionPolicy policy) {}
  };

  private static ObsLog vital(final String name, final double value, final String rating,
      final String route) {
    return new ObsLog(System.currentTimeMillis(), "ui", "INFO", "app-logger", "web-vital", null,
        null, null, Map.of("log.args", "[{\"name\":\"" + name + "\",\"value\":" + value
            + ",\"rating\":\"" + rating + "\",\"route\":\"" + route + "\"}]"),
        "1.0", "prod");
  }

  @Test
  @DisplayName("The ids of the pages are replaced, so a page is one series")
  void page() {
    Assertions.assertEquals("/orders/:id/lines", ObserveMetrics.page("/orders/123/lines?x=1"));
    Assertions.assertEquals("/users/:id",
        ObserveMetrics.page("/users/3f2b1c9e-1d2a-4f5b-9a8c-1234567890ab"));
    Assertions.assertEquals("/", ObserveMetrics.page(null));
  }

  @Test
  @DisplayName("Vitals per page: p75, poor share; CLS keeps its unit")
  void vitals() {
    ObserveMetrics metrics = new ObserveMetrics(EMPTY, 100);
    metrics.recordVital(vital("LCP", 1200, "good", "/orders/1"));
    metrics.recordVital(vital("LCP", 5200, "poor", "/orders/2"));
    metrics.recordVital(vital("CLS", 0.05, "good", "/orders/3"));
    metrics.recordVital(
        new ObsLog(0, "ui", "INFO", "x", "other", null, null, null, Map.of(), null, null));
    long now = System.currentTimeMillis();
    List<Map<String, Object>> rows = metrics.vitals(Set.of(), now - 3_600_000, now + 60_000);
    Assertions.assertEquals(2, rows.size());
    Map<String, Object> lcp =
        rows.stream().filter(r -> "LCP".equals(r.get("name"))).findFirst().orElseThrow();
    Assertions.assertEquals("/orders/:id", lcp.get("page"));
    Assertions.assertEquals(2L, lcp.get("samples"));
    Assertions.assertEquals(50.0, lcp.get("poorRate"));
    Map<String, Object> cls =
        rows.stream().filter(r -> "CLS".equals(r.get("name"))).findFirst().orElseThrow();
    Assertions.assertTrue((Double) cls.get("p75") < 0.1);
  }
}
